mapper.select:
SELECT COUNT(DISTINCT cs.student_id)
FROM class_students cs
WHERE cs.class_id IN (
    SELECT cc.id FROM course_classes cc WHERE cc.course_id = #{courseId}
    UNION
    SELECT cc_c.class_id FROM class_courses cc_c WHERE cc_c.course_id = #{courseId}
)

mapper.insert:
INSERT INTO exam_classes (exam_id, class_id)
SELECT DISTINCT #{examId}, class_id FROM (
    SELECT cc.id AS class_id FROM course_classes cc
    WHERE cc.course_id = #{courseId} AND cc.teacher_id = #{teacherId}
    UNION
    SELECT cc_c.class_id AS class_id FROM class_courses cc_c
    WHERE cc_c.course_id = #{courseId} AND cc_c.teacher_id = #{teacherId}
) AS all_classes
